mkitem!{mkstruct!{# [doc = " Wraps a writer and buffers output to it, flushing whenever a newline"] # [doc = " (`0x0a`, `'\\n'`) is detected."] # [doc = ""] # [doc = " The [`BufWriter`] struct wraps a writer and buffers its output."] # [doc = " But it only does this batched write when it goes out of scope, or when the"] # [doc = " internal buffer is full. Sometimes, you'd prefer to write each line as it's"] # [doc = " completed, rather than the entire buffer at once. Enter `LineWriter`. It"] # [doc = " does exactly that."] # [doc = ""] # [doc = " Like [`BufWriter`], a `LineWriter`’s buffer will also be flushed when the"] # [doc = " `LineWriter` goes out of scope or when its internal buffer is full."] # [doc = ""] # [doc = " If there's still a partial line in the buffer when the `LineWriter` is"] # [doc = " dropped, it will flush those contents."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " We can use `LineWriter` to write one line at a time, significantly"] # [doc = " reducing the number of actual writes to the file."] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::{self, File};"] # [doc = " use std::io::prelude::*;"] # [doc = " use std::io::LineWriter;"] # [doc = ""] # [doc = " fn main() -> std::io::Result<()> {"] # [doc = "     let road_not_taken = b\"I shall be telling this with a sigh"] # [doc = " Somewhere ages and ages hence:"] # [doc = " Two roads diverged in a wood, and I -"] # [doc = " I took the one less traveled by,"] # [doc = " And that has made all the difference.\";"] # [doc = ""] # [doc = "     let file = File::create(\"poem.txt\")?;"] # [doc = "     let mut file = LineWriter::new(file);"] # [doc = ""] # [doc = "     file.write_all(b\"I shall be telling this with a sigh\")?;"] # [doc = ""] # [doc = "     // No bytes are written until a newline is encountered (or"] # [doc = "     // the internal buffer is filled)."] # [doc = "     assert_eq!(fs::read_to_string(\"poem.txt\")?, \"\");"] # [doc = "     file.write_all(b\"\\n\")?;"] # [doc = "     assert_eq!("] # [doc = "         fs::read_to_string(\"poem.txt\")?,"] # [doc = "         \"I shall be telling this with a sigh\\n\","] # [doc = "     );"] # [doc = ""] # [doc = "     // Write the rest of the poem."] # [doc = "     file.write_all(b\"Somewhere ages and ages hence:"] # [doc = " Two roads diverged in a wood, and I -"] # [doc = " I took the one less traveled by,"] # [doc = " And that has made all the difference.\")?;"] # [doc = ""] # [doc = "     // The last line of the poem doesn't end in a newline, so"] # [doc = "     // we have to flush or drop the `LineWriter` to finish"] # [doc = "     // writing."] # [doc = "     file.flush()?;"] # [doc = ""] # [doc = "     // Confirm the whole poem was written."] # [doc = "     assert_eq!(fs::read(\"poem.txt\")?, &road_not_taken[..]);"] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub struct LineWriter < W : ? Sized + Write > { inner : BufWriter < W > , }}}
